import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        Function<String, String> besar = String::toUpperCase;
        System.out.println(besar.apply("halo"));

        Function<String, Integer> keAngka = Integer::parseInt;
        int hasil = keAngka.apply("40") + 2;
        System.out.println(hasil);

        Predicate<Integer> genap = Main::cekGenap;
        System.out.println(genap.test(7));

        Supplier<List<String>> buatList = ArrayList::new;
        List<String> daftar = buatList.get();
        daftar.add("baru");
        System.out.println(daftar);

        Consumer<String> cetak = System.out::println;
        cetak.accept("selesai");
    }

    static boolean cekGenap(int n) {
        return n % 2 == 0;
    }
}

