cards.solution:
import java.util.function.Function;
import java.util.function.Predicate;

public class Main {
    public static void main(String[] args) {
        Function<String, Integer> panjang = String::length;
        System.out.println(panjang.apply("generics"));
        Predicate<Integer> positif = Main::cekPositif;
        System.out.println(positif.test(-3));
    }

    static boolean cekPositif(int n) {
        return n > 0;
    }
}

